class Solution {
    public int[] getAverages(int[] nums,int k){
        int[] answer=new int[nums.length];
        Arrays.fill(answer,-1);
        int window=2*k+1;
        if(window>nums.length)return answer;
        long sum=0;
        for(int i=0;i<window;i++)sum+=nums[i];
        for(int center=k;center+k<nums.length;center++){
            answer[center]=(int)(sum/window);
            if(center+k+1<nums.length)sum+=nums[center+k+1]-nums[center-k];
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getAverages(nums:IntArray,k:Int):IntArray{
        val answer=IntArray(nums.size){
            -1
        };
        val window=2*k+1;
        if(window>nums.size)return answer;
        var sum=0L;
        for(i in 0 until window)sum+=nums[i];
        for(center in k until nums.size-k){
            answer[center]=(sum/window).toInt();
            if(center+k+1<nums.size)sum+=nums[center+k+1]-nums[center-k]
        };
        return answer
    }
}

